func TestAssignmentQueue_DiscardRemovesPendingVolume(t *testing.T) {
	q := newAssignmentQueue()
	q.enqueue(AssignmentAsk{
		VolumeID: "v1", ReplicaID: "r1", DataAddr: "d1", CtrlAddr: "c1", Intent: IntentBind,
	})
